/* Round22 presentation. Scientific statements come from reviewed gate data. */
(() => {
  'use strict';
  const prior = window.ResearchObservatory, D = window.ROUND22_DATA;
  const esc = x => String(x ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const list = x => Array.isArray(x)?x:[];
  const route = (key,label,cls='') => `<a class="${cls}" href="#research/${key}">${esc(label)}</a>`;
  const repo = 'https://github.com/occult-kranti/yang_mills_workbench/blob/main/';
  const link = (path,label) => `<a href="${repo}${esc(path)}">${esc(label)} ↗</a>`;
  const paragraph = x => `<p>${esc(x)}</p>`;
  const formula = x => `<div class="r22-formula">${esc(x)}</div>`;
  const badge = x => `<span class="rc-badge rc-${esc(x)}">${x==='limited'?'Supported with limits':x==='rejected'?'Target rejected':'Accepted in stated model'}</span>`;
  const loop = id => D.loops.find(x=>x.loop===id);
  const evidence = x => `<div class="r22-evidence">${link(`research/round22/contracts/${x.loop}.json`,'Frozen contract')}${link(`research/round22/forward/${x.loop}/report.md`,'Forward proof')}${link(`research/round22/reverse/${x.loop}/report.md`,'Reverse reconstruction')}${link(`research/round22/skeptic/${x.loop}.md`,'Skeptical review')}${link(`research/round22/advisor/${x.loop}-gate.json`,'Admission and sources')}</div>`;
  const nav = () => `<nav class="rc-nav" aria-label="Round22 research navigation">${route('home','Current research')}${route('journey','Scrolling journey')}${route('contributions','Contributions')}${route('round22-roadmap','Roadmap')}${route('round22-review','Evidence')}${route('round21-home','Round21 history')}</nav>`;
  const limits = x => `<div class="r22-limit"><strong>Next missing premise</strong>${paragraph(x.next_missing_premise)}<ul>${list(x.limitations).map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div>`;
  function card(x) {
    return `<article class="rc-result r22-result"><div class="rc-result-meta"><span class="rc-index">${x.loop.toUpperCase()}</span>${badge(x.status)}</div><p class="r21-classification">${esc(x.novelty_category)}</p><h3>${esc(x.title)}</h3>${paragraph(x.claim)}${list(x.equations).map(formula).join('')}<p class="rc-scope"><strong>Scope:</strong> ${esc(x.scope)}</p>${paragraph(x.target_verdict)}${route('round22-'+x.loop,'Read derivation and review →','rc-text-link')}</article>`;
  }
  function next() {
    return `<section class="rc-section r22-next"><p class="rc-kicker">After ten reviews</p><h2>The next three goals</h2>${list(D.next.goals).map(g=>`<article><h3>${esc(g.id)} · ${esc(g.title)}</h3>${paragraph(g.target||g.first_loop_target)}${paragraph(g.missing_premise||g.reason)}</article>`).join('')}<p>These goals are planned. This release does not count or execute an eleventh research loop.</p>${link('research/round22/advisor/post-ten-roadmap.json','Selection record')}</section>`;
  }
  function models() {
    return `<section class="rc-section"><h2>Keep the models and scales distinct</h2><div class="r22-table-wrap" role="region" aria-label="Models and physical scales" tabindex="0"><table class="r22-model-table"><thead><tr><th>Model</th><th>Fixed premises</th><th>What varies</th><th>Limit of the claim</th></tr></thead><tbody>${list(D.models).map(m=>`<tr><th>${esc(m.name)}</th><td>${esc(m.fixed)}</td><td>${esc(m.varied)}</td><td>${esc(m.boundary)}</td></tr>`).join('')}</tbody></table></div></section>`;
  }
  function home() {
    return `<section class="rc-hero"><div><p class="rc-kicker">Round22 · independent paired research</p><h1>${esc(D.title)}</h1><div class="rc-hero-deck">${paragraph(D.summary)}</div><div class="rc-hero-actions">${route('journey','Follow the research journey','rc-button')}${route('round22-review','Inspect the evidence →','rc-hero-link')}</div></div><aside class="rc-score"><span class="rc-score-number">10<span>/ 10</span></span><strong>Research loops reviewed</strong><p>${D.accepted} accepted · ${D.limited} limited${D.rejected?` · ${D.rejected} rejected`:""}</p><small>This counts completed investigations, not the fraction of the continuum problem solved.</small></aside></section><div class="r21-novelty"><strong>What these results establish</strong>${paragraph(D.novelty_note)}<p>The four-dimensional continuum Yang–Mills construction and mass gap remain open. Scientific priority remains unverified.</p></div>${models()}<section class="rc-section"><h2>Supported contributions and their limits</h2><div class="rc-results rc-results-all">${D.loops.map(card).join('')}</div></section>${next()}`;
  }
  function loopPage(x) {
    return `<header class="r22-page-head"><p class="rc-kicker">Round22 · ${x.loop.toUpperCase()}</p><h1>${esc(x.title)}</h1>${badge(x.status)}${paragraph(x.claim)}</header><section class="rc-section"><h2>Original question</h2>${paragraph(x.contract.target||x.contract.goal)}<details class="r22-proposed"><summary>Frozen proposal and acceptance criteria</summary><p>This is the proposal as frozen before investigation. The accepted statement is shown separately below.</p><pre>${esc(JSON.stringify({proposal:x.contract.proposed_not_accepted,acceptance:x.contract.acceptance,required:x.contract.required},null,2))}</pre></details><h2>Supported statement</h2>${list(x.equations).map(formula).join('')}<p class="rc-scope"><strong>Assumptions and model:</strong> ${esc(x.scope)}</p>${paragraph(x.target_verdict)}</section><section class="rc-section"><h2>Derivation</h2><ol class="r22-steps">${x.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="rc-pair-cards"><section><h3>Forward derivation</h3>${paragraph(x.forward)}</section><section><h3>Reverse reconstruction</h3>${paragraph(x.reverse)}</section></div><h3>Skeptical objection</h3>${paragraph(x.objection)}<h3>Exception or amended hypothesis</h3>${paragraph(x.exception)}${limits(x)}</section><section class="rc-section"><h2>Evidence and attribution</h2><p>${esc(x.novelty_category)}. ${esc(x.prior_work)} Scientific priority remains unverified.</p>${evidence(x)}<details><summary>Independence disclosure</summary><pre>${esc(JSON.stringify(x.independence,null,2))}</pre></details><p>${x.bound_files} source and output files are bound to this admission.</p><code class="r22-hash">${esc(x.gate_sha256)}</code><h3>Reproduce</h3><pre>python3 -B research/round22/reproduce.py --loops ${x.loop} --output /absolute/new/${x.loop}-replay</pre><details><summary>Model, domain, parameters and units</summary><pre>${esc(JSON.stringify(x.contract,null,2))}</pre></details></section>${route('round22-roadmap','← Five-goal roadmap','rc-text-link')}`;
  }
  function roadmap() {
    return `<header class="r22-page-head"><p class="rc-kicker">Feedback record</p><h1>Five goals. Ten research loops.</h1><p>Each second loop was selected after its first skeptical review. Q and R were selected after all six N/O/P loops.</p></header>${list(D.goals).map(g=>`<section class="rc-section"><p class="rc-kicker">Goal ${esc(g.id)}</p><h2>${esc(g.title)}</h2>${paragraph(g.reason)}<div class="rc-pair-cards">${D.loops.filter(x=>x.loop[0]===g.id.toLowerCase()).map(card).join('')}</div></section>`).join('')}${link('research/round22/advisor/post-six-selection.json','Six-loop selection')}${next()}`;
  }
  function review() {
    return `<header class="r22-page-head"><p class="rc-kicker">Evidence review</p><h1>Every claim has a scope.</h1><p>Proofs, executable checks and publication verification answer different questions. Hashes bind the evidence; the written arguments and skeptical reviews support the mathematics.</p></header><div class="rc-review-grid">${D.loops.map(x=>`<article class="rc-review-card"><h2>${x.loop.toUpperCase()} · ${esc(x.title)}</h2>${badge(x.status)}${paragraph(x.target_verdict)}${evidence(x)}${route('round22-'+x.loop,'Open full review →')}</article>`).join('')}</div><section class="rc-section"><h2>Complete-cycle audit</h2>${link('research/round22/skeptic/post-ten-review.md','Skeptical ten-loop audit')}${link('research/round22/advisor/progress-ledger.json','Progress ledger')}${link('research/round22/advisor/exception-ledger.json','Exception ledger')}${link('research/round22/advisor/claim-dependency-map.json','Claim and dependency map')}${link('research/round22/skeptic/post-six-review.md','Six-loop skeptical checkpoint')}${link('research/round22/release/protocol.md','Release verification protocol')}<p>Ordinary and optimized Python replays, admission mutation controls and clean Git-tree validation are recorded separately from the ten research loops.</p></section>`;
  }
  function evaluateBound(q,gamma) {
    if(typeof q!=='number'||typeof gamma!=='number'||!Number.isFinite(q)||!Number.isFinite(gamma)||q<=0||q>=1||gamma<0||gamma>4)throw new RangeError('Require 0<q<1 and 0≤gamma≤4.');
    const budget=x=>(2+5*x+5*x*x+6*x**3+3*x**4)/(24*(1-x)**3*(1+x)**2*(1+x*x));
    const tau=.5/(8*budget(q)),sigma=tau*Math.sqrt(budget(q*q)/96),state=6*sigma/.0625,time=(1-q)**(-gamma),D_local=(1+3*q+4*q*q+4*q**3+2*q**4)/12,support=2*time*tau*D_local;
    return {q,gamma,state,support,D_local,total:state+support,time,certified:gamma<3};
  }
  function journey() {
    return `<article class="r22-journey"><header class="r22-journey-hero"><p class="rc-kicker">Round22 · forward derivation ↔ reverse reconstruction</p><h1>A sharper bound.<br>A more precise<br><em>remaining problem.</em></h1>${paragraph(D.summary)}<p class="j-status">Ten loops reviewed. The continuum problem remains open.</p><div class="r22-journey-links">${list(D.goals).map(g=>`<button data-r22-go="${esc(g.id)}">${esc(g.id)} · ${esc(g.title)}</button>`).join('')}</div></header><section class="r22-journey-section"><p class="rc-kicker">The accepted N1 improvement</p><h2>Compare stationary observables.</h2><div class="r22-hero-equation">|C<sub>q</sub>(t) − C<sub>ref</sub>(t)|<br>≤ ‖A‖ ‖B‖ [6d<sub>q</sub> + <span>2ατ<sub>q</sub>|t|D<sub>F<sub>B</sub></sub>(q)/ℏ</span>]</div><p>Stationary Heisenberg evolution removes the scalar phase from observable conjugation. The new dynamic estimate uses the complete local support. The state-distance term remains.</p><p><strong>Fixed bounded local observables:</strong> sufficient windows 0 ≤ γ &lt; 3. Actual behavior at γ = 3 remains unresolved.</p><div class="r22-calculator"><h3>Inspect the sufficient error bound</h3><p>Equation values, not measured correlation errors. Fixed α = ℏ = 1, C = 1, η = 1/2 and unit observable norms; the complete origin-xz cover has 22 links.</p><label>Profile q <output id="r22-q-value">0.9</output><input id="r22-q" type="range" min="0.75" max="0.999" step="0.001" value="0.9"></label><label>Window exponent γ<select id="r22-gamma"><option value="0">0 · fixed time</option><option value="1.5">1.5 · now certified</option><option value="2.5" selected>2.5 · growing, certified</option><option value="3">3 · certificate insufficient</option><option value="3.5">3.5 · beyond certificate</option></select></label><div aria-live="polite" id="r22-bound-output"></div><p>The calculator uses the exact 28-face budget D = (1 + 3q + 4q² + 4q³ + 2q⁴)/12 and d ≤ σ/ḡ. A nonvanishing upper bound does not prove actual nonconvergence.</p></div>${route('round22-n1','Read the full proof and controls →')}</section>${list(D.goals).map(g=>`<section id="r22-chapter-${esc(g.id)}" tabindex="-1" class="r22-journey-section"><p class="rc-kicker">Goal ${esc(g.id)} · two feedback loops</p><h2>${esc(g.title)}</h2>${paragraph(g.reason)}${D.loops.filter(x=>x.loop[0]===g.id.toLowerCase()).map(card).join('')}</section>`).join('')}<section class="r22-journey-section"><h2>What a continuum solution still requires</h2>${list(D.continuum_obligations).map(paragraph).join('')}<p>The paired spirals organize the research method. No Fibonacci law or new universal constant has been established.</p>${next()}${route('journey21','Read the frozen Round21 journey →')}</section></article>`;
  }
  const owned = r => ['home','contributions','round22-roadmap','round22-review','journey'].includes(r)||/^round22-[n-r][12]$/.test(r);
  const historicLinks = html => html.replaceAll('href="#research/home"','href="#research/round21-home"').replaceAll('href="#research/contributions"','href="#research/round21-contributions"').replaceAll('href="#research/journey"','href="#research/journey21"');
  function render(r='home') {
    if(r==='round21-home'||r==='round21-contributions')return `<div class="rc-history-notice">Round21 release record. ${route('home','Return to current research →')}</div>`+historicLinks(prior.render(r==='round21-home'?'home':'contributions'));
    if(r==='journey21')return `<div class="rc-history-notice">Frozen Round21 journey; its next goals were pending at that release. ${route('journey','Current journey →')}</div>`+historicLinks(prior.render('journey'));
    if(!owned(r)){const html=prior.render(r);return r.startsWith('round21-')||['review20-home','contributions20'].includes(r)?historicLinks(html):html;}
    const content=r==='home'?home():r==='journey'?journey():r==='contributions'?`<header class="r22-page-head"><p class="rc-kicker">Contribution ledger</p><h1>Supported results, with their limits.</h1>${paragraph(D.novelty_note)}</header><div class="rc-results rc-results-all">${D.loops.map(card).join('')}</div>`:r==='round22-roadmap'?roadmap():r==='round22-review'?review():loopPage(loop(r.slice(8)));
    return `<div class="rc20 r21 r22">${nav()}${content}<footer class="rc-footer"><strong>Yang–Mills Workbench · Round22</strong>${route('round22-review','Evidence review')}${route('round21-home','Round21 history')}</footer></div>`;
  }
  function afterRender() {
    window.ResearchJourney?.cleanup?.();
    const r=location.hash.split('/')[1]||'home';
    if(r==='round21-home'||r==='round21-contributions'){document.title='Round21 '+(r==='round21-home'?'research record':'contributions')+' · Yang–Mills Workbench';return;}
    if(!owned(r)){prior.afterRender();return;}
    document.title=(r==='journey'?'Round22 research journey':r.startsWith('round22-')?r.slice(8).toUpperCase()+' · Round22':'Round22 research')+' · Yang–Mills Workbench';
    if(r!=='journey')return;
    document.querySelectorAll('[data-r22-go]').forEach(button=>button.addEventListener('click',()=>{const target=document.getElementById('r22-chapter-'+button.dataset.r22Go);target.focus({preventScroll:true});target.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}));
    const input=document.getElementById('r22-q'),gamma=document.getElementById('r22-gamma');
    if(input&&gamma){const update=()=>{const b=evaluateBound(Number(input.value),Number(gamma.value));document.getElementById('r22-q-value').textContent=b.q.toFixed(3);document.getElementById('r22-bound-output').innerHTML=`<strong>${b.total.toPrecision(5)}</strong><p>State: ${b.state.toPrecision(4)} · local dynamics: ${b.support.toPrecision(4)}</p><p>${b.certified?'Certified asymptotic range as q → 1.':'This certificate is insufficient; actual nonconvergence is not implied.'}</p>`;};input.addEventListener('input',update);gamma.addEventListener('change',update);update();}
  }
  window.ResearchRound22={render,afterRender,data:D,evaluateBound};
  window.ResearchObservatory={...prior,render,afterRender};
})();
